-- 594: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 1 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_594_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_594_guard;
INSERT INTO _migration_594_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_001' AND NOT (q.topic_id IS 'topic_igcse_chem_atomic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An atom of carbon-14 has proton number 6 and nucleon number 14. How many neutrons does the atom contain?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 8","B. 6","C. 14","D. 20"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Number of neutrons = nucleon number − proton number = 14 − 6 = 8. (6 is the number of protons; 14 is the nucleon number; 20 adds the numbers instead of subtracting.) Therefore the correct answer is A: 8.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_001' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_594_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_002' AND NOT (q.topic_id IS 'topic_igcse_chem_atomic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An element X has atomic number 12. What is the electronic configuration of an atom of X?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 2,8,8","B. 2,8,2","C. 8,2,2","D. 2,10"]' AND q.correct_answer IS 'B' AND q.explanation IS 'An atom of X has 12 electrons. The first shell holds 2 electrons and the second holds 8, leaving 2 in the third shell: 2,8,2. (2,8,8 is argon with 18 electrons; 8,2,2 fills the shells in the wrong order.) Therefore the correct answer is B: 2,8,2.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_002' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_594_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_003' AND NOT (q.topic_id IS 'topic_igcse_chem_atomic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which sub-atomic particle has a charge of −1 and a negligible mass?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Proton","B. Neutron","C. Electron","D. Alpha particle"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The electron has a relative charge of −1 and a relative mass of about 1/1840, which is negligible. (A proton has charge +1 and relative mass 1; a neutron is neutral with relative mass 1; an alpha particle is a helium nucleus of charge +2.) Therefore the correct answer is C: Electron.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_003' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_594_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_004' AND NOT (q.topic_id IS 'topic_igcse_chem_atomic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Magnesium has atomic number 12. How many electrons are there in one Mg²⁺ ion?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 12","B. 14","C. 8","D. 10"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A neutral magnesium atom has 12 electrons. The Mg²⁺ ion forms when the atom loses its two outer-shell electrons, leaving 12 − 2 = 10 electrons. (14 wrongly adds the charge; 12 ignores it; 8 is only the second-shell population.) Therefore the correct answer is D: 10.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_004' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_001', 'topic_igcse_chem_atomic', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'An atom of carbon-14 has proton number 6 and nucleon number 14. How many neutrons does the atom contain?', 'multiple_choice', NULL, '["A. 8","B. 6","C. 14","D. 20"]', 'A', 'Number of neutrons = nucleon number − proton number = 14 − 6 = 8. (6 is the number of protons; 14 is the nucleon number; 20 adds the numbers instead of subtracting.) Therefore the correct answer is A: 8.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_cambridge');
