INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_003', 'topic_igcse_chem_atomic', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which sub-atomic particle has a charge of −1 and a negligible mass?', 'multiple_choice', NULL, '["A. Proton","B. Neutron","C. Electron","D. Alpha particle"]', 'C', 'The electron has a relative charge of −1 and a relative mass of about 1/1840, which is negligible. (A proton has charge +1 and relative mass 1; a neutron is neutral with relative mass 1; an alpha particle is a helium nucleus of charge +2.) Therefore the correct answer is C: Electron.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_004', 'topic_igcse_chem_atomic', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Magnesium has atomic number 12. How many electrons are there in one Mg²⁺ ion?', 'multiple_choice', NULL, '["A. 12","B. 14","C. 8","D. 10"]', 'D', 'A neutral magnesium atom has 12 electrons. The Mg²⁺ ion forms when the atom loses its two outer-shell electrons, leaving 12 − 2 = 10 electrons. (14 wrongly adds the charge; 12 ignores it; 8 is only the second-shell population.) Therefore the correct answer is D: 10.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_cambridge');
